function printDiagramBlocks(group,scope){const rows=scope?scope.all.filter(n=>n.group===group):nodes.filter(n=>n.group===group),parents=new Map();for(const n of rows){const p=n.parentRef||'Raiz';if(!parents.has(p))parents.set(p,[]);parents.get(p).push(n)}const blocks=[];for(const [parent,a] of parents){const label=byId.get(parent)?.tag||'Documento / raiz';for(let i=0;i<a.length;i+=12){const chunk=a.slice(i,i+12),part=Math.floor(i/12)+1,count=Math.ceil(a.length/12);blocks.push(`<article class="print-block"><div class="print-block-header"><b>${safe(label)} <span style="font-size:8pt">(${safe(parent)})</span></b><small>${chunk.length} elementos · Parte ${part}/${count}${part>1?' — continuação do grupo pai':''}</small></div><div class="print-connector">↓ relação pai → filhos do catálogo</div><table><thead><tr><th>Identificador e tag</th><th>Ocorrência / descrição</th></tr></thead><tbody>${chunk.map(n=>`<tr><td>${safe(n.id)} · ${safe(n.tag)}${scope&&!scope.chosen.has(n.key)?' <small>(pai de contexto)</small>':''}</td><td>${scope&&!scope.chosen.has(n.key)?'—':safe(n.occur||'—')}<small style="display:block;color:#536e80">${scope&&!scope.chosen.has(n.key)?'Somente contexto hierárquico':safe($('#printDetail').value==='short'?'':(n.description||'Descrição não informada'))}</small></td></tr>`).join('')}</tbody></table>${part<count?'<p class="print-continued">Este grupo continua no bloco seguinte.</p>':''}</article>`)} }return `<div class="print-blocks">${blocks.join('')}</div>`;}
