function integratedHierarchy(scope){const ordered=orderedScope(scope);return `<section class="print-integrated-section" data-integrated-section="tree"><h2>2. Explorador Hierárquico · caminho dos campos selecionados</h2><p class="print-source">Os ancestrais não selecionados estão sinalizados como contexto hierárquico, sem integrar a contagem de campos escolhidos.</p><div class="print-integrated-tree">${ordered.map(({n,d})=>{const context=!scope.chosen.has(n.key);return `<div class="print-integrated-tree-row ${context?'only-context':''}" data-integrated-key="${safe(n.key)}" data-context="${context}" style="--indent:${Math.min(d,11)}"><span class="integrated-tree-line">├─</span><b>${safe(n.id)} · ${safe(n.tag)}</b><small>${context?'CONTEXTO — não selecionado':'SELECIONADO'} · ${safe(n.occur||'—')}</small></div>`}).join('')}</div></section>`;}
