 const slots=new Map();let cursor=pad;function place(k){const kids=local.get(k)||[],bh=heights.get(k);if(!kids.length){const y=cursor+bh/2;cursor+=bh+vgap;slots.set(k,y);return y;}const start=cursor,ys=kids.map(place);let center=(ys[0]+ys[ys.length-1])/2;const top=center-bh/2;if(top<start){const delta=start-top;for(const [key,y] of slots)if(y>=start)slots.set(key,y+delta);center+=delta;cursor+=delta;}cursor=Math.max(cursor,center+bh/2+vgap);slots.set(k,center);return center;}
