 const size=$('#pageSize').value,land=$('#pageOrient').value==='landscape',margin=Number($('#printMargin').value)||12,font=Number($('#printFont').value)||10,mono=$('#printColor').value==='bw',detail=$('#diagramDetail').value;
 const mm=size==='A3'?[297,420]:[210,297],maxW=(mm[land?1:0]-2*margin-3)*96/25.4,maxH=(mm[land?0:1]-2*margin-31)*96/25.4;
