 const labels=(n,ref)=>{const context=!scope.chosen.has(n.key);return [...wrap(n.id+' · '+n.tag,true).map(t=>({t,b:true})),...wrap(ref?'CONTINUAÇÃO · referência':context?'CONTEXTO · não selecionado':'SELECIONADO').map(t=>({t})),...wrap('Ocor. '+(n.occur||'—')+' · '+(n.type||'—')).map(t=>({t})),...(!ref&&!context&&detail!=='short'?wrap(detail==='full'?(n.xpath||'XPath não confirmado'):(n.description||'Descrição não informada')).map(t=>({t})):[])];};
 const layout=(entries)=>{const items=new Map(entries.map(e=>[e.n.key,e])),childrenLocal=new Map(),roots=[];for(const e of entries){const p=printSelection.parent.get(e.n.key);if(items.has(p)){const a=childrenLocal.get(p)||[];a.push(e);childrenLocal.set(p,a);}else roots.push(e);}const slots=new Map(),depths=new Map(),lines=new Map();let leaf=0,maxDepth=0,bh=0;for(const e of entries){const l=labels(e.n,e.ref);lines.set(e.n.key,l);bh=Math.max(bh,18+l.length*(fs+3));}if(compact){const coords=new Map(entries.map((e,i)=>[e.n.key,{x:i===0?6:34,y:6+i*(bh+gy)}]));return {w:bw+46,h:entries.length*(bh+gy)-gy+12,bh,coords,lines,items};}function walk(e,d){depths.set(e.n.key,d);maxDepth=Math.max(maxDepth,d);const subs=childrenLocal.get(e.n.key)||[],a=subs.map(x=>walk(x,d+1));const pos=a.length?(a[0]+a[a.length-1])/2:leaf++;slots.set(e.n.key,pos);return pos;}roots.forEach(e=>walk(e,0));const w=vertical?leaf*(bw+gx)-gx+12:(maxDepth+1)*(bw+gx)-gx+12,h=vertical?(maxDepth+1)*(bh+gy)-gy+12:leaf*(bh+gy)-gy+12;const coords=new Map(entries.map(e=>[e.n.key,{x:6+(vertical?slots.get(e.n.key):depths.get(e.n.key))*(bw+gx),y:6+(vertical?depths.get(e.n.key):slots.get(e.n.key))*(bh+gy)}]));return {w,h,bh,coords,lines,items};};
 const pages=[];let entries=[];const add=e=>{const p=printSelection.parent.get(e.n.key);const ref=p&&map.has(p)&&!entries.some(x=>x.n.key===p)?[{n:map.get(p),ref:true}]:[];return [...entries,...ref,{n:e.n,ref:false}];};
