 const margin=Number($('#printMargin').value)||12,[w,h]=pageDimensions($('#pageSize').value,$('#pageOrient').value).split(' ').map(parseFloat),fs=Math.max(7,Number($('#printFont').value)-1.5),mode=$('#printFit').value;
