printPresets=printPresetsRead();refreshPrintPresets();$('#printSavePreset').onclick=()=>{const name=$('#printPresetName').value.trim().slice(0,80);if(!name){$('#printSelectionMessage').textContent='Informe um nome para salvar.';return;}printPresets[name]={keys:[...printSelection.selected],savedAt:new Date().toISOString(),catalogVersion:data.metadata?.version||'desconhecida'};$('#printSelectionMessage').textContent=printPresetsWrite()?'Seleção salva neste navegador.':'Armazenamento local indisponível; use exportação CSV.';refreshPrintPresets();$('#printPresetList').value=name};$('#printLoadPreset').onclick=()=>{const k=$('#printPresetList').value,p=printPresets[k];if(!p)return;printSelection.reset(nodes,p.keys||[]);syncPrintSelection();$('#printSelectionMessage').textContent='Seleção carregada. Campos inexistentes na base atual foram ignorados.'};$('#printDeletePreset').onclick=()=>{const k=$('#printPresetList').value;if(!k)return;delete printPresets[k];printPresetsWrite();refreshPrintPresets()};$('#printSelectedCsv').onclick=()=>{const rows=buildPrintSelectionData().rows;const values=[['ID','Campo','Grupo','Descrição','Pai','Tipo','Ocorrência','XPath'],...rows.map(n=>[n.id,n.tag,n.group,n.description,n.parent,n.type,n.occur,n.xpath])];download('selecao_impressao_nfe.csv','\ufeff'+values.map(r=>r.map(csvValue).join(';')).join('\r\n'),'text/csv;charset=utf-8')};
$('#printScope').onchange=()=>{$('#printGroupsMulti').hidden=$('#printScope').value!=='multi';printable()};['printSectionMoc','printSectionTree','printSectionDict','printSectionDiagram','printType','printGroup','pageSize','pageOrient','printFont','printMargin','printDetail','printDiagramFormat','printMocMode','printMap','printFit','printColor','printCover','printSummary','printDiagrams','printDictionary','printOracle','printHistory'].forEach(id=>$('#'+id).onchange=printable);$('#printGroupsMulti').onchange=printable;$('#printType').onchange=()=>{if($('#printType').value==='official')$('#printMocMode').value='official';else if(['group','integrated','integrated-full'].includes($('#printType').value))$('#printMocMode').value='hierarchy';printable()};function selectedReportPDF(){if(document.documentElement.dataset.appVersion!=='2.3.19'||DfePdfExport.version!=='2.3.19')throw new Error('Arquivos de versões diferentes. Atualize o pacote completo e recarregue a página (Ctrl+F5).');printable();if($('#btnDownloadPdf').disabled)return null;const plan=printLayout||planPrint();const root=document.createElement('div');if(plan)for(const p of plan.pages)root.append(p.cloneNode(true));return DfePdfExport.createPDF(plan?root:$('#printDocument'),printOptions(plan?.profile));}
