$('#btnDoPrint').onclick=()=>{if(!printSelection.count())return;try{const pdf=selectedReportPDF();if(!pdf)return;const url=URL.createObjectURL(pdf);const tab=window.open(url,'_blank');if(!tab){download(reportPDFName(),pdf,'application/pdf');URL.revokeObjectURL(url);$('#printOutputStatus').textContent='Nova aba bloqueada. PDF baixado; abra o arquivo e imprima em tamanho real (100%).';}else{try{tab.opener=null}catch{}$('#printOutputStatus').textContent='PDF aberto em nova aba. Imprima no leitor de PDF em tamanho real (100%), no mesmo formato de papel.';/* A aba pode continuar aberta; o URL é liberado quando esta página é encerrada. */}}catch(e){alert('Não foi possível abrir o PDF: '+e.message);}};
